"""Claude Code adapter.

Payload: {"tool_name", "tool_input", "session_id", "tool_use_id", "hook_event_name", ...}
Response: {"hookSpecificOutput": {"hookEventName", "permissionDecision", ...}} on stdout;
exit 2 also blocks. Verified live against Claude Code 2.1.245 (2026-08-25)."""



AGENT = "claude_code"

# vendor event name -> canonical
EVENT_MAP = {
    "PreToolUse": PRE_TOOL,
    "PostToolUse": POST_TOOL,
    "PostToolUseFailure": TOOL_FAILURE,
    "UserPromptSubmit": PROMPT_SUBMIT,
    "SessionStart": SESSION_START,
    "SessionEnd": SESSION_END,
    "Stop": STOP,
    "PreCompact": PRE_COMPACT,
    "SubagentStart": SUBAGENT_START,
    "SubagentStop": SUBAGENT_STOP,
    # Both were claimed by the matrix long before they were mapped here, so an install for
    # them wired nothing at all and said nothing about it. FileChanged fires when a watched
    # file changes on disk (the matcher names the files); InstructionsLoaded fires when a
    # CLAUDE.md or .claude/rules/*.md is read into context, at session start and again
    # whenever one is loaded lazily.
    "InstructionsLoaded": INSTRUCTIONS_LOADED,
    "FileChanged": FILE_CHANGED,
}
REVERSE_EVENT_MAP = {v: k for k, v in EVENT_MAP.items()}

# Tools whose input carries file content rather than a shell command.
WRITE_TOOLS = ("Write", "Edit", "MultiEdit", "NotebookEdit")

#: The tool a shell command arrives under, and therefore what a PreToolUse `matcher` must say
#: to gate shell. A wrong value fails silently: it matches nothing, and the install looks fine.
SHELL_TOOLS = ("Bash",)


#: Fields observed in real Claude Code payloads (live capture, v3.17.8 era, 2026-08-27) that
#: no other adapter's documented envelope lists. Positive evidence, not inferred absence --
#: which is the distinction that broke detection here. `prompt_id` was once treated as proof
#: a payload was NOT Claude Code's; Claude Code now sends it on nearly every event, so that
#: negative test rejected 38 of 42 real payloads and handed them to Devin instead.
OBSERVED_MARKERS = (
    "transcript_path",
    "permission_mode",
    "stop_hook_active",
    "agent_transcript_path",
    "background_tasks",
    "session_crons",
    "custom_instructions",
    "effort",
)


def looks_like_claude_code(raw):
    """True when the payload carries a field only Claude Code has been seen to send.

    Imported by the adapters that share this envelope, so the discriminator lives in one
    place and cannot drift into two disagreeing copies.
    """
    return isinstance(raw, dict) and any(marker in raw for marker in OBSERVED_MARKERS)


def claims(raw):
    """True when this payload looks like Claude Code's shape."""
    if not isinstance(raw, dict):
        return False
    if raw.get("hook_event_name") in EVENT_MAP:
        # Codex reuses tool_input but adds turn identifiers, and Devin reuses the whole
        # event vocabulary but adds a per-turn prompt_id. Claiming either would make
        # detect() ambiguous, and an unidentified payload is allowed through.
        # Kimi Code CLI is Claude Code's envelope exactly -- same PascalCase events, same
        # snake_case fields -- and names itself only in client_type.
        if raw.get("client_type") not in (None, "claude_code"):
            return False
        # Junie reuses this whole event vocabulary on purpose -- it says so -- and sends
        # project_path, which Claude Code does not. Without this the two are one payload.
        # Foreign nameplates: Codex's turn_id, Junie's project_path, Tabnine's timestamp.
        # None appears in any real Claude Code payload observed live, and each is the only
        # documented thing separating that vendor's identically-named events from ours.
        if "turn_id" in raw or "project_path" in raw or "timestamp" in raw:
            return False
        # `prompt_id` used to be treated as proof this was Devin's payload, not ours. Claude
        # Code now sends it too, so the field alone settles nothing: it is only Devin's when
        # nothing we have actually observed from Claude Code is alongside it.
        if "prompt_id" in raw and not looks_like_claude_code(raw):
            return False
        return True
    return False


def parse(raw):
    ti = raw.get("tool_input")
    # A guard that crashes is a guard that allows: dispatch only wraps the JSON decode, so
    # an exception here kills the hook with exit 1, which most vendors treat as a
    # non-blocking error and let the call through. tool_input is whatever the agent chose
    # to serialise, so it is not ours to assume the shape of.
    ti = tool_input_of(ti)
    tool = raw.get("tool_name")
    # new_source is NotebookEdit's cell body -- the tool is in WRITE_TOOLS, so claiming to
    # handle it while dropping its content is an internal contradiction, not a vendor guess.
    content = ti.get("content") or ti.get("new_string") or ti.get("new_source") or None
    if content is None and isinstance(ti.get("edits"), list):
        joined = "\n".join(str(e.get("new_string", "")) for e in ti["edits"] if isinstance(e, dict))
        content = joined or None
    out = raw.get("tool_output")
    if isinstance(out, (dict, list)):
        import json as _json

        out = _json.dumps(out)
    return Event(
        AGENT,
        # An event this adapter has no mapping for resolves to UNKNOWN, never to the
        # nearest canonical one: relabelling it invites a guardrail to evaluate the
        # wrong policy against it.
        EVENT_MAP.get(raw.get("hook_event_name"), UNKNOWN),
        tool=tool,
        command=ti.get("command"),
        # InstructionsLoaded and FileChanged carry no tool_input at all -- file_path (and,
        # for InstructionsLoaded, content) sit at the top level instead, per the project's
        # own recorded example payloads (examples/generated/claude_code.md).
        path=ti.get("file_path") or ti.get("path") or ti.get("notebook_path") or raw.get("file_path"),
        content=content or raw.get("content"),
        output=out,
        prompt=raw.get("prompt"),
        session_id=raw.get("session_id"),
        tool_use_id=raw.get("tool_use_id"),
        cwd=raw.get("cwd"),
        raw=raw,
    )


#: Events that read a TOP-LEVEL {"decision": "block", "reason": ...} and ignore
#: hookSpecificOutput.permissionDecision entirely. Established live against 2.1.247
#: (2026-08-28) -- two reads of the vendor page gave contradictory answers. See respond().
_BLOCK_DIALECT_EVENTS = (PROMPT_SUBMIT, STOP)


def _refusal_reason(decision):
    """One reason string for the events that can only block -- no ask, no rewrite.

    Both degrade to a block with the degradation named rather than being dropped: silence
    at a blocking event is the dispatcher's allow, which is not what the caller asked for.
    """
    reason = decision.reason or "blocked by policy"
    if decision.outcome == ASK:
        return reason + " (confirmation requested; this event cannot prompt, so it blocks)"
    if decision.outcome == REWRITE:
        return reason + " (input rewrite requested; this event cannot modify input, so it blocks)"
    return reason


#: Decision words this vendor accepts. allow/deny/ask are permissionDecision's, honoured at
#: pre_tool; "block" is the top-level dialect prompt_submit and stop read. Established live
#: against 2.1.247 (2026-08-28).
DECISION_VOCABULARY = frozenset({"allow", "deny", "ask", "block"})


#: hookSpecificOutput.additionalContext -- docs-basis, NOT the live-verified 2.1.247
#: experiment below. code.claude.com/docs/en/hooks documents this as how a hook injects text
#: into Claude's own context, explicitly nested (top-level is silently ignored), with a
#: SessionStart example naming it and a UserPromptSubmit section for the same purpose.
def _additional_context_output(event, context):
    return {
        "hookSpecificOutput": {
            "hookEventName": REVERSE_EVENT_MAP.get(event.event, "PreToolUse"),
            "additionalContext": context,
        }
    }


def respond(decision, event):
    """(stdout_text, exit_code) for this decision -- three dialects, not one.

    Until 2026-08-28 this emitted hookSpecificOutput.permissionDecision at EVERY event.
    A live experiment against Claude Code 2.1.247 settled what each event actually reads,
    by wiring one candidate shape per trial and watching the agent rather than the hook:

        event             {"decision": "block"}   hookSpecificOutput   exit 2
        UserPromptSubmit  honoured                IGNORED              honoured
        Stop              honoured                IGNORED              honoured
        PreToolUse        --                      honoured             --

    So every prompt_submit and stop deny this library has ever produced on its most-used
    adapter was silently discarded: the handler refused, the dispatcher reported a block,
    and the prompt reached the model anyway. At prompt_submit the trial prompt asked the
    agent to write a marker file and the file appeared; at stop the agent carried on and
    the Stop hook re-fired with stop_hook_active set. Both signals are things the agent
    did, not things the probe claimed.

    exit 2 works at both, and is deliberately NOT used: it collapses to 1 under the
    PowerShell wrapper some vendors apply, and it leaks the full hook command line into the
    UI where the JSON form does not. The JSON block also carries the reason into context.

    pre_tool keeps hookSpecificOutput.permissionDecision, and that was verified in the same
    round rather than assumed: a deny there blocked the Write outright, and the agent's next
    Bash call too, so the gate fires for every tool. It must keep this shape in any case --
    it is the only one carrying updatedInput, which rewrite depends on. Everything else is
    observation-only in this row and gets silence: a verdict there was never read.

    A bare ALLOW is SILENCE, not permissionDecision:"allow".

    "The handler has no objection" and "skip the user's own permission prompt" are different
    statements, and only the first is what a guardrail means. The vendor's documentation
    settles what silence does, verbatim: "Exit code 0 with no output means the hook has no
    decision to report, so the tool call continues through the normal permission flow."
    What an explicit "allow" does there is NOT documented -- so the recorded option keeps
    the user's own protection. VS Code's languageModelToolsService, read from source, returns
    `autoConfirmed: ConfirmationNotNeeded` on exactly this value -- which VOUCH exists to
    speak on purpose (see below, and allow_semantics.VOUCH_SPEAKS) on the two vendors this is
    established for. REWRITE still sends an explicit allow, since updatedInput is the only
    way to express one and approving the *substituted* call is what was asked for.
    """
    import json as _json

    if event.event in _BLOCK_DIALECT_EVENTS:
        # VOUCH has no word here either -- only ever spoken at pre_tool below -- so it is a
        # louder allow this dialect cannot hear.
        out = {} if decision.outcome in (ALLOW, VOUCH) else {"decision": "block", "reason": _refusal_reason(decision)}
        # additionalContext is a second, independent key; only UserPromptSubmit of this pair
        # is documented to take it.
        if event.event == PROMPT_SUBMIT and decision.context:
            out.update(_additional_context_output(event, decision.context))
        return (_json.dumps(out), 0) if out else ("", 0)

    if event.event == SESSION_START:
        # Silent regardless of outcome (no block/rewrite claimed here) except for context.
        if decision.context:
            return _json.dumps(_additional_context_output(event, decision.context)), 0
        return "", 0

    if event.event != PRE_TOOL:
        return "", 0

    if decision.outcome == ALLOW:
        return "", 0

    out = {"hookEventName": REVERSE_EVENT_MAP.get(event.event, "PreToolUse")}
    if decision.outcome == VOUCH:
        # Reaches here undegraded only because allow_semantics.VOUCH_SPEAKS names
        # claude_code (see dispatch.degrade()) -- the word a bare ALLOW withholds above.
        out["permissionDecision"] = "allow"
        if decision.reason:
            out["permissionDecisionReason"] = decision.reason
    elif decision.outcome == DENY:
        out["permissionDecision"] = "deny"
        out["permissionDecisionReason"] = decision.reason or "blocked"
    elif decision.outcome == ASK:
        out["permissionDecision"] = "ask"
        out["permissionDecisionReason"] = decision.reason or "confirmation required"
    elif decision.outcome == REWRITE:
        out["permissionDecision"] = "allow"
        out["updatedInput"] = decision.updated_input
        if decision.reason:
            out["permissionDecisionReason"] = decision.reason
    return _json.dumps({"hookSpecificOutput": out}), 0


def hook_config(canonical_events, command, matcher=None):
    """A settings.json `hooks` fragment wiring `command` for these canonical events."""
    hooks = {}
    for ev in canonical_events:
        name = REVERSE_EVENT_MAP.get(ev)
        if not name:
            continue
        entry = {"hooks": [{"type": "command", "command": command}]}
        if matcher:
            entry["matcher"] = matcher
        hooks.setdefault(name, []).append(entry)
    return {"hooks": hooks}


CONFIG_PATH = ".claude/settings.json"


# ------------------------------------------------------------------------------
# runtime (agentseam dispatch, specialized to claude_code)

_VOUCH_SPEAKS = True
_REWRITE_EVENTS = frozenset(('pre_tool',))


def degrade(decision, event):
    """Reduce a decision to what 'claude_code' can actually honor, honestly.

    This is agentseam.dispatch.degrade(), specialized to one fixed agent so this file needs
    no "import agentseam" -- claude_code and vscode_copilot are the only agents with real evidence that an explicit approval word means "skip confirmation"; see agentseam.allow_semantics.
    """
    if decision.outcome == REWRITE and event.event not in _REWRITE_EVENTS:
        evidence = dict(decision.evidence)
        evidence["degraded_from"] = REWRITE
        return Decision.ask(decision.reason or "input requires modification before it can run", evidence=evidence)
    if decision.outcome == VOUCH and not _VOUCH_SPEAKS:
        evidence = dict(decision.evidence)
        evidence["degraded_from"] = VOUCH
        return Decision.allow(decision.reason, evidence=evidence, context=decision.context)
    return decision


# >>> agentseam handler >>>
GUARD_VIOLATION = 1

_BASH_CANDIDATES = ('bash', 'C:\\Program Files\\Git\\usr\\bin\\bash.exe', 'C:\\Program Files\\Git\\bin\\bash.exe', 'C:\\Program Files (x86)\\Git\\usr\\bin\\bash.exe', '/bin/bash', '/usr/bin/bash')

GATE_LOG_ENV = 'CHOCK_GATE_LOG'

_LOG_MAX_BYTES = 1048576

_GUARD_TIMEOUT_SECONDS = 30

def guard_path_from_argv(argv: list[str]) -> _chock_Path | None:
    """The `--guard <path>` argument a vendored runtime was invoked with, or None.

    Read straight off argv rather than through argparse: every event a vendored runtime is
    ever invoked for goes through the same command line, chosen at install time
    (`hooks/*_install.py`), so there is nothing else on it to parse.
    """
    if '--guard' in argv:
        i = argv.index('--guard')
        if i + 1 < len(argv):
            return _chock_Path(argv[i + 1])
    return None

def find_bash(guard: _chock_Path) -> str | None:
    """First interpreter that can actually see `guard`, or None.

    The probe runs `test -f <guard>` rather than `--version`: the question is not whether
    a bash exists but whether *this* bash can resolve the path we are about to hand it.
    """
    for candidate in _BASH_CANDIDATES:
        try:
            proc = _chock_subprocess.run([candidate, '-c', f'test -f "{guard.as_posix()}"'], capture_output=True, timeout=10)
        except (OSError, _chock_subprocess.SubprocessError):
            continue
        if proc.returncode == 0:
            return candidate
    return None

def run_guard(guard: _chock_Path, command: str) -> bool | None:
    """True when the guard ran and reported a violation, False when it ran clean.

    None means the check did not happen -- unparseable command, no usable bash, a crash.
    That is distinct from False and must stay distinct: every "not checked" path still
    allows, so folding it into False changes no verdict, but it would let the outcome log
    record a passing guard for a check that never ran.

    Nothing here blocks on its own failure. Treating "could not run" as a violation would
    stop every Bash call the moment bash was missing -- turning a best-effort guard into a
    total outage. Failing open is stated loudly on stderr instead of silently.
    """
    try:
        args = _chock_shlex.split(command)
    except ValueError:
        print('chock: could not parse command (unbalanced quotes), not checked', file=sys.stderr)
        return None
    if not args:
        return None
    bash = find_bash(guard)
    if bash is None:
        print(f'chock: no usable bash found, {guard.name} not checked', file=sys.stderr)
        return None
    try:
        env = {**_chock_os.environ, 'CHOCK_RAW_COMMAND': command}
        proc = _chock_subprocess.run([bash, str(guard), *args], capture_output=True, text=True, encoding='utf-8', errors='replace', env=env, timeout=_GUARD_TIMEOUT_SECONDS)
    except (OSError, UnicodeError, _chock_subprocess.TimeoutExpired) as exc:
        print(f'chock: guard could not run, not checked: {exc}', file=sys.stderr)
        return None
    if proc.returncode == GUARD_VIOLATION:
        sys.stderr.write(proc.stdout or '')
        sys.stderr.write(proc.stderr or '')
        if not ((proc.stdout or '') + (proc.stderr or '')).strip():
            print(f'chock: blocked by {_chock_Path(guard).name} (guard gave no reason)', file=sys.stderr)
        return True
    if proc.returncode != 0:
        detail = (proc.stderr or proc.stdout or '').strip().splitlines()
        print(f'chock: guard exited {proc.returncode}, not checked' + (f': {detail[0][:120]}' if detail else ''), file=sys.stderr)
        return None
    return False

def log_outcome(guard: _chock_Path, tool: str, blocked: bool) -> None:
    """Append one outcome record. Best effort: never raises, never changes the verdict.

    Deliberately records NO command and no guard output. The command is the scanned content
    here, and commands routinely carry bearer tokens and passwords -- writing them to a
    plaintext file on every Bash call would create the exposure the secret policies exist to
    prevent. Which policy, which tool, and allow-or-block is the whole useful signal.
    """
    try:
        if _chock_os.environ.get(GATE_LOG_ENV) == '0':
            return
        guard = guard.resolve()
        if guard.parent.name != 'implementations':
            return
        artifact_root = None
        for parent in guard.parents:
            if (parent / '.chock').is_dir():
                artifact_root = parent / '.chock'
                break
        if artifact_root is None:
            return
        log_dir = artifact_root / 'log'
        log_dir.mkdir(parents=True, exist_ok=True)
        log_path = log_dir / 'gate-events.jsonl'
        if log_path.exists() and log_path.stat().st_size > _LOG_MAX_BYTES:
            log_path.replace(log_dir / 'gate-events.1.jsonl')
        import json
        record = {'ts': _chock_datetime.now(_chock_timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'), 'policy_id': guard.parent.parent.name, 'surface': 'pre-tool-use', 'event': 'tool_use', 'kind': guard.stem, 'tool': tool, 'verdict': 'block' if blocked else 'allow'}
        with log_path.open('a', encoding='utf-8') as fh:
            fh.write(json.dumps(record, ensure_ascii=False) + '\n')
    except Exception:
        return

def evaluate(argv: list[str], command: str, tool: str='') -> str | None:
    """Run the guard named on `argv` (`--guard <path>`) against `command`.

    Returns the deny reason when the guard reports a violation, None on allow (including
    every "not checked" case -- the guard's own stderr already explains those). The one
    caller-facing entry point `gate.runtime_bundle`'s spliced handler uses: locate the
    guard, run it, log the outcome, word the verdict.
    """
    guard = guard_path_from_argv(argv)
    if guard is None or not guard.exists():
        return None
    blocked = run_guard(guard, command)
    if blocked is not None:
        log_outcome(guard, tool, blocked)
    return f'Blocked by chock policy: {guard.stem}' if blocked else None

_INSTRUCTION = "Chock: this clone's git hooks are NOT installed -- git never clones hooks, so commit-time gates will not run locally until someone runs:\n    pip install chock && chock sync --repo .\nRun that before the first commit. (The repo's CI gate, where wired, enforces regardless.)"

def _repo_root() -> _chock_Path:
    root = _chock_os.environ.get('CLAUDE_PROJECT_DIR')
    return _chock_Path(root) if root else _chock_Path.cwd()

def _hooks_pre_commit(repo_root: _chock_Path) -> _chock_Path | None:
    """The active pre-commit hook path, honouring core.hooksPath. None when git is absent."""
    try:
        proc = _chock_subprocess.run(['git', 'rev-parse', '--git-path', 'hooks'], cwd=repo_root, capture_output=True, text=True, timeout=15)
    except (OSError, _chock_subprocess.TimeoutExpired):
        return None
    if proc.returncode != 0:
        return None
    hooks = _chock_Path(proc.stdout.strip())
    if not hooks.is_absolute():
        hooks = repo_root / hooks
    return hooks / 'pre-commit'

def _armed(repo_root: _chock_Path) -> bool:
    pre_commit = _hooks_pre_commit(repo_root)
    if pre_commit is None:
        return True
    try:
        return pre_commit.exists() and 'chock' in pre_commit.read_text(encoding='utf-8', errors='replace').lower()
    except OSError:
        return False

def _chock_importable() -> bool:
    import importlib.util
    try:
        return importlib.util.find_spec('chock') is not None
    except (ImportError, ValueError):
        return False


def _chock_handle_session_start(event):
    repo_root = _repo_root()
    if not (repo_root / ".chock").is_dir():
        return None  # not a chock-managed repo
    if _armed(repo_root):
        return None

    if _chock_importable():
        try:
            proc = _chock_subprocess.run(
                [sys.executable, "-m", "chock", "sync", "--repo", str(repo_root)],
                cwd=repo_root,
                capture_output=True,
                text=True,
                timeout=240,
            )
        except (OSError, _chock_subprocess.TimeoutExpired):
            proc = None
        if proc is not None and proc.returncode == 0 and _armed(repo_root):
            return Decision.allow(
                context=(
                    "Chock: this clone's git hooks were not installed (git never clones hooks); "
                    "armed them now with `chock sync`."
                )
            )

    return Decision.allow(context=_INSTRUCTION)


def handle(event):
    if event.event == "pre_tool" and event.command:
        reason = evaluate(sys.argv[1:], event.command, event.tool or "")
        return Decision.deny(reason) if reason else None
    if event.event == "session_start":
        return _chock_handle_session_start(event)
    return None
# <<< agentseam handler <<<


def _coerce(result):
    if result is None:
        return Decision.allow()
    if isinstance(result, Decision):
        return result
    raise TypeError("handle() must return a Decision or None, got %r" % (type(result),))


def _read_payload(stream):
    # Decode bytes ourselves rather than trust the platform locale -- a BOM'd or non-UTF-8
    # stdin must not silently disable the gate. See agentseam.dispatch for the incident
    # this guards: a Windows console's cp1252 layer turning a UTF-8 BOM into three bytes
    # json cannot parse, with the hook allowing everything while claiming enforcement.
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        return buffer.read().decode("utf-8-sig", errors="replace")
    return stream.read().lstrip("\ufeff")


def _emit(out, text):
    buffer = getattr(out, "buffer", None)
    if buffer is not None:
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        out.write(text)
        out.flush()


def main(stdin=None, stdout=None, exit=True):
    """Read one payload from stdin, dispatch, emit the 'claude_code' response, exit."""
    stream = stdin if stdin is not None else sys.stdin
    out = stdout if stdout is not None else sys.stdout
    try:
        raw = json.loads(_read_payload(stream))
    except Exception:
        # Malformed input is not the agent's fault to pay for: allow, stay silent.
        if exit:
            sys.exit(0)
        return 0
    event = parse(raw)
    if event.event == UNKNOWN:
        # A vendor event this adapter has no mapping for. handle() is not called: it
        # reasons about the canonical vocabulary, and handing it something outside that
        # vocabulary invites a decision made on a false premise.
        if exit:
            sys.exit(0)
        return 0
    decision = degrade(_coerce(handle(event)), event)
    text, code = respond(decision, event)
    if text:
        _emit(out, text)
    if exit:
        sys.exit(code)
    return code


if __name__ == "__main__":  # pragma: no cover
    main()

